def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_run(col):
        cells = [(r, grid[r][col]) for r in range(h) if grid[r][col] != bg]
        runs = []
        for r, color in cells:
            if runs and runs[-1][1] == color and runs[-1][2] == r - 1:
                runs[-1] = (runs[-1][0], color, r)
            else:
                runs.append((r, color, r))
        return runs

    left_runs = edge_run(0)
    right_runs = edge_run(w - 1)
    if not left_runs or not right_runs:
        return out

    # Use the longest colored run on each vertical edge.
    left = max(left_runs, key=lambda x: x[2] - x[0])
    right = max(right_runs, key=lambda x: x[2] - x[0])
    l0, _, l1 = left
    r0, _, r1 = right

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != bg
               and not (c == 0 or c == w - 1)]

    for r, c, color in markers:
        if r0 <= r <= r1:
            # Marker aligned with the right-edge segment.
            idx = r - r0
            counterpart = l0 + idx
            out[r][c] = 4
            for x in range(c + 1, w - 1):
                out[r][x] = color
            if l0 <= counterpart <= l1:
                for x in range(1, w):
                    out[counterpart][x] = color
        elif l0 <= r <= l1:
            # Marker aligned with the left-edge segment.
            idx = r - l0
            counterpart = r0 + idx
            out[r][c] = 4
            for x in range(1, c):
                out[r][x] = color
            if r0 <= counterpart <= r1:
                for x in range(w - 1):
                    out[counterpart][x] = color

    return out
